const exportJournalLines = `-- name: ExportJournalLines :many

SELECT
    j.id                                                                     AS journal_id,
    j.journal_date,
    j.reference,
    j.memo,
    j.kind::TEXT                                                             AS kind,
    j.is_adjusting,
    a.code,
    a.name                                                                   AS account_name,
    le.description,
    le.debit,
    le.credit
FROM journals j
JOIN ledger_entries le ON le.journal_id = j.id AND le.company_id = j.company_id
JOIN accounts a ON a.id = le.account_id AND a.company_id = le.company_id
WHERE j.company_id = $1
  AND j.journal_date >= $2
  AND j.journal_date <= $3
ORDER BY j.journal_date, j.id, le.id
`

