const monthlyProfitLoss = `-- name: MonthlyProfitLoss :many

SELECT
    to_char(date_trunc('month', j.journal_date), 'YYYY-MM')                    AS bulan,
    COALESCE(SUM(CASE WHEN a.account_type = 'revenue' THEN le.credit - le.debit ELSE 0 END), 0)::NUMERIC(20, 2) AS pendapatan,
    COALESCE(SUM(CASE WHEN a.account_type = 'expense' THEN le.debit - le.credit ELSE 0 END), 0)::NUMERIC(20, 2) AS beban,
    COUNT(DISTINCT j.id)::BIGINT                                             AS jumlah_jurnal
FROM journals j
JOIN ledger_entries le ON le.journal_id = j.id AND le.company_id = j.company_id
JOIN accounts a ON a.id = le.account_id AND a.company_id = le.company_id
WHERE j.company_id = $1
  AND j.journal_date >= $2
  AND j.journal_date <= $3
GROUP BY 1
ORDER BY 1
`

type MonthlyProfitLossParams struct {
	CompanyID int64
	DateFrom  pgtype.Date
	DateTo    pgtype.Date
}

type MonthlyProfitLossRow struct {
	Bulan        string
	Pendapatan   pgtype.Numeric
	Beban        pgtype.Numeric
	JumlahJurnal int64
}

// ============================================================
// Dashboard: seri bulanan pendapatan, beban, dan laba
// ============================================================
func (q *Queries) MonthlyProfitLoss(ctx context.Context, arg MonthlyProfitLossParams) ([]MonthlyProfitLossRow, error) {
	rows, err := q.db.Query(ctx, monthlyProfitLoss, arg.CompanyID, arg.DateFrom, arg.DateTo)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []MonthlyProfitLossRow{}
	for rows.Next() {
		var i MonthlyProfitLossRow
		if err := rows.Scan(
			&i.Bulan,
			&i.Pendapatan,
			&i.Beban,
			&i.JumlahJurnal,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

